import fetch from "node-fetch";
import { calcularCRC } from "./src/tst.js";

const charPerByte = 2;
const hexOpciones = {
  auth: "d00000000067003836313531383034303937363837390000000000007573657200000000000000000000000000000000007061737300000000000000000000000000000000004e6f6d627265416c417a6172000000000000000000000000000000000000000000000000000000009081",
  ask: "c000010029000013c4",
  info: "",
  trama:
    "a2010000005100945b776369070000005653435a31343034393737320952433030303038353936353832382c312c2d35095831303230094130094630343130094250313456413034393737324509516030094339303a360d812f",
  grupo:
    "",
  fallo: "cc00010029000013c4",
  end: "c200000000000016F6",
};

const hexCabecera = {
  auth: "d000",
  ask: "c000",
  info: "b000",
  trama: "a201",
  grupo: "e004",
  fallo: "cc00",
  end: "c200",
};
const hexCuerpo = {
  auth: "67003836313531383034303937363837390000000000007573657200000000000000000000000000000000007061737300000000000000000000000000000000004e6f6d627265416c417a6172000000000000000000000000000000000000000000000000000000009081",
  ask: "000013c4",
  info: "",
  trama:
    "5100945b776369070000005653435a31343034393737320952433030303038353936353832382c312c2d35095831303230094130094630343130094250313456413034393737324509516030094339303a360d812f",
  grupo:
    "",
  fallo: "000013c4",
  end: "000016F6",
};

function nombreAHexRellenado(nombre) {
  // Convertir a Buffer con terminador nulo
  const buffer = Buffer.from(nombre + "\x00", "ascii");

  // Rellenar hasta 40 bytes
  const relleno = Buffer.alloc(40 - buffer.length, 0x00);

  // Concatenar y convertir a string hexadecimal
  const completo = Buffer.concat([buffer, relleno]);
  return completo.toString("hex");
}

const opcion = process.argv[2] || "fallo"; // por defecto 'a' si no se pasa nada
const cabecera = process.argv[3] || "000000"; // Frame, SesionH, SesionL

if (process.argv[4] && process.argv[4].length > 0) {
  const name = nombreAHexRellenado(process.argv[4]);
  hexCuerpo.auth =
    hexOpciones.auth.slice(5 * charPerByte, 68 * charPerByte) +
    name +
    hexOpciones.auth.slice(108 * charPerByte);
}

let hex =
  hexCabecera[opcion].toLowerCase() +
  cabecera.toLowerCase() +
  hexCuerpo[opcion].toLowerCase();

if (!hex) {
  console.error(`Opción inválida: ${opcion}`);
  process.exit(1);
}

hex = hex.substring(0, hex.length - 4);
hex = hex + calcularCRC(hex);

console.log(`Enviando ${hex}`);
const url = `http://localhost:9999/${encodeURIComponent(hex)}`;

async function enviarHex() {
  try {
    const res = await fetch(url);
    const buffer = await res.arrayBuffer();
    const respuesta = Buffer.from(buffer).toString("hex");
    console.log("Respuesta recibida:");
    console.log(`buffer : ${buffer}`);
    console.log(`respuesta: ${respuesta}`);
    console.log(`Responder a ${respuesta.slice(4, 10)}`);
  } catch (err) {
    console.error("Error al enviar GET:", err.message);
  }
}

enviarHex();
